package com.bank.ledger.wal;

import java.util.UUID;

/**
 * Report generated by AuditVerifierService during cryptographic verification of the ledger.
 *
 * @param totalTransactionsScanned number of transactions audited
 * @param valid                    true if all double-entry, link, and hash checks succeeded
 * @param calculatedMerkleRoot     the resulting Merkle root hash
 * @param corruptedSequenceNum     sequence number of the corrupted record (null if valid)
 * @param corruptedTransactionId   ID of the corrupted transaction (null if valid)
 * @param failureReason            detailed message describing any discrepancy
 */
public record AuditVerificationReport(
    long totalTransactionsScanned,
    boolean valid,
    String calculatedMerkleRoot,
    Long corruptedSequenceNum,
    UUID corruptedTransactionId,
    String failureReason
) {
    public static AuditVerificationReport success(long totalScanned, String merkleRoot) {
        return new AuditVerificationReport(totalScanned, true, merkleRoot, null, null, null);
    }

    public static AuditVerificationReport failure(
        long totalScanned,
        long sequenceNum,
        UUID transactionId,
        String reason
    ) {
        return new AuditVerificationReport(totalScanned, false, null, sequenceNum, transactionId, reason);
    }
}
